import { Accordion, Separator, Text } from "@chakra-ui/react";
import type { ReactNode } from "react";
import { RasaCodeBlock } from "../../RasaCodeBlock";
import { ErrorAlert } from "../../try-assistant/ConversationLog/Event/ErrorAlert";
import type { ConversationEvent, ToolSource } from "../../types";
import { CommonEventInfo, EventAccordionItem, InfoField } from "./blocks";

export type RawToolEvent = {
  tool_name?: string;
  arguments?: Record<string, unknown>;
  result?: unknown;
  is_error?: boolean;
  error_message?: string;
  source?: ToolSource;
  mcp_server?: string;
};

interface ToolRunEventBodyProps {
  event: ConversationEvent;
  extraFields?: ReactNode;
  /** Label for the owning-resource field: "Skill" (Mantle) or "Flow" (v1). */
  resourceLabel: string;
}

function formatToolResult(result: unknown): string {
  if (result == null) {
    return "—";
  }
  return typeof result === "string" ? result : JSON.stringify(result, null, 2);
}

export const ToolRunEventBody = ({ event, extraFields, resourceLabel }: ToolRunEventBodyProps) => {
  const rawEvent = event.metadata?.rawEvent as RawToolEvent | undefined;
  const toolName = event.metadata?.tool_name ?? rawEvent?.tool_name ?? event.name ?? "tool";
  const argumentsValue = event.metadata?.tool_arguments ?? rawEvent?.arguments ?? null;
  const resultValue = event.metadata?.tool_result ?? rawEvent?.result;
  const isError = event.metadata?.tool_is_error === true || rawEvent?.is_error === true;
  const errorMessage = event.metadata?.tool_error_message ?? rawEvent?.error_message;
  const mcpServer = event.metadata?.tool_mcp_server ?? rawEvent?.mcp_server;

  return (
    <>
      <InfoField label="Tool">
        <Text textStyle="sm">{toolName}</Text>
      </InfoField>

      {extraFields}

      {mcpServer && (
        <InfoField label="Server">
          <Text textStyle="sm">{mcpServer}</Text>
        </InfoField>
      )}

      {event.flowId && (
        <InfoField label={resourceLabel}>
          <Text textStyle="sm">{event.flowId}</Text>
        </InfoField>
      )}

      <InfoField label="Arguments">
        <RasaCodeBlock
          code={argumentsValue != null ? JSON.stringify(argumentsValue, null, 2) : "—"}
          data-testid="event-mcp-tool-arguments"
          maxCodeHeight="48"
        />
      </InfoField>

      {isError ? (
        <ErrorAlert
          title={
            errorMessage
              ? "This tool call failed to execute due to the following reason:"
              : "This tool call failed to execute"
          }
          message={errorMessage}
        />
      ) : (
        <InfoField label="Result">
          <RasaCodeBlock
            code={formatToolResult(resultValue)}
            data-testid="event-mcp-tool-result"
            maxCodeHeight="80"
          />
        </InfoField>
      )}

      <Separator mt="2" />
      <Accordion.Root collapsible multiple>
        <EventAccordionItem title="Event details" value="event-details">
          <CommonEventInfo event={event} />
        </EventAccordionItem>
      </Accordion.Root>
    </>
  );
};
